#include "mpas_f32.cuh"
typedef int M4Failure;
// One zero-initialized int32 flag per refusal source; integer atomics are deterministic.
__device__ __forceinline__ void m4_fail(M4Failure *f,unsigned long long slot,unsigned long long field,unsigned long long index,unsigned long long source){(void)slot;(void)field;(void)index;atomicExch(&f[source-1],1);}
struct M4Term {float br,bd,bv,b4,bh,bfactor;double b4_64,bh_64;bool valid;};
__device__ __forceinline__ M4Term m4_term(int e,int k,const float*rho,const float*div,const float*vort,const float*d4,const int*coe,const int*voe,const float*dc,const float*dv,float h4,float divf,int nc,int ne,int nv,float seed){
 M4Term t={};int c0=coe[2*e],c1=coe[2*e+1],v0=voe[2*e],v1=voe[2*e+1];if(c0<0||c0>=nc||c1<0||c1>=nc||v0<0||v0>=nv||v1<0||v1>=nv||c0==c1||v0==v1)return t;
 float x=dc[e],y=dv[e],r=rho[k*ne+e],d=d4[e],a=div[k*nc+c0],b=div[k*nc+c1],p=vort[k*nv+v0],q=vort[k*nv+v1];if(!isfinite(x)||x==0||!isfinite(y)||y==0||!isfinite(r)||!isfinite(d)||!isfinite(h4)||!isfinite(divf)||!isfinite(a)||!isfinite(b)||!isfinite(p)||!isfinite(q)||!isfinite(seed))return t;
 float id=1.0f/x,iv=fminf(1.0f/y,4.0f*id),scale=mpas_mul(d,h4),rdc=mpas_mul(mpas_mul(scale,divf),id),rdv=mpas_mul(scale,iv),delta=mpas_sub(b,a),omega=mpas_sub(q,p),inner=mpas_sub(mpas_mul(delta,rdc),mpas_mul(omega,rdv));
 float bs=mpas_mul(-seed,r),brdc=mpas_mul(bs,delta),brdv=-mpas_mul(bs,omega),bscale=mpas_add(mpas_mul(mpas_mul(brdc,id),divf),mpas_mul(brdv,iv));
 t.br=-mpas_mul(seed,inner);t.bd=mpas_mul(bs,rdc);t.bv=-mpas_mul(bs,rdv);t.b4=mpas_mul(bscale,h4);t.bh=mpas_mul(bscale,d);t.bfactor=mpas_mul(mpas_mul(brdc,id),scale);
 double bscale64=mpas_f32_to_f64_ieee(mpas_mul(mpas_mul(brdc,id),divf))+mpas_f32_to_f64_ieee(mpas_mul(brdv,iv));t.b4_64=bscale64*mpas_f32_to_f64_ieee(h4);t.bh_64=bscale64*mpas_f32_to_f64_ieee(d);
 t.valid=isfinite(t.br)&&isfinite(t.bd)&&isfinite(t.bv)&&isfinite(t.b4)&&isfinite(t.bh)&&isfinite(t.bfactor);return t;
}
extern "C" __global__ void momentum_filter_lap4_v841_f32__tl(const float*rho,const float*div,const float*vort,const float*d4,const int*coe,const int*voe,const float*dc,const float*dv,const float h4,const float divf,const int nlev,const int nc,const int ne,const int nv,float*tend,const float*drho,const float*ddiv,const float*dvort,const float*dd4,const float*dh4,const float*ddivf,float*dtend,M4Failure*failure){
 (void)tend;int e=blockIdx.x*blockDim.x+threadIdx.x;if(e>=ne)return;int c0=coe[2*e],c1=coe[2*e+1],v0=voe[2*e],v1=voe[2*e+1];
 for(int k=0;k<nlev;++k){int i=k*ne+e;M4Term t=m4_term(e,k,rho,div,vort,d4,coe,voe,dc,dv,h4,divf,nc,ne,nv,1.0f);if(!t.valid){m4_fail(failure,i, 1, i, 1);continue;}
  float z=dtend[i];z=mpas_add(z,mpas_mul(t.br,drho[i]));z=mpas_add(z,mpas_mul(t.bd,mpas_sub(ddiv[k*nc+c1],ddiv[k*nc+c0])));z=mpas_add(z,mpas_mul(t.bv,mpas_sub(dvort[k*nv+v1],dvort[k*nv+v0])));z=mpas_add(z,mpas_mul(t.b4,dd4[e]));z=mpas_add(z,mpas_mul(t.bh,*dh4));z=mpas_add(z,mpas_mul(t.bfactor,*ddivf));if(!isfinite(z)){m4_fail(failure,i, 15, i, 2);continue;}dtend[i]=z;
 }
}
extern "C" __global__ void momentum_filter_lap4_v841_f32__ad(const float*rho,const float*div,const float*vort,const float*d4,const int*coe,const int*voe,const float*dc,const float*dv,const float h4,const float divf,const int nlev,const int nc,const int ne,const int nv,float*tend,const float*bt_snapshot,float*bt,float*brho,float*bdiv,float*bvort,float*bd4,float*bh4,float*bdivf,float*bt_in,const int*eoc,const int*neoc,const int*eov,const int max_edges,const int degree,M4Failure*failure){
 (void)tend;int first=blockIdx.x*blockDim.x+threadIdx.x,stride=gridDim.x*blockDim.x;unsigned long long nedge=(unsigned long long)nlev*ne,ncell=(unsigned long long)nlev*nc,nvert=(unsigned long long)nlev*nv;
 for(int i=first;i<nlev*ne;i+=stride){int e=i%ne,k=i/ne;M4Term t=m4_term(e,k,rho,div,vort,d4,coe,voe,dc,dv,h4,divf,nc,ne,nv,bt_snapshot[i]);if(!t.valid||!isfinite(brho[i])||!isfinite(bt_in[i])){m4_fail(failure,i, 1, i, 3);continue;}brho[i]=mpas_add(brho[i],t.br);bt_in[i]=mpas_add(bt_in[i],bt_snapshot[i]);bt[i]=0;}
