 for(int i=first;i<nlev*nv;i+=stride){int v=i%nv,k=i/nv;double b=mpas_f32_to_f64_ieee(bvort[i]);unsigned long long slot=nedge+ncell+i;if(!isfinite(b)){m4_fail(failure,slot, 3, i, 9);continue;}for(int j=0;j<degree;++j){int e=eov[v*degree+j];if(e<0)continue;if(e>=ne){m4_fail(failure,slot, 3, i, 10);continue;}int v0=voe[2*e],v1=voe[2*e+1];if(v!=v0&&v!=v1){m4_fail(failure,slot, 3, i, 11);continue;}M4Term t=m4_term(e,k,rho,div,vort,d4,coe,voe,dc,dv,h4,divf,nc,ne,nv,bt_snapshot[k*ne+e]);if(!t.valid){m4_fail(failure,slot, 3, i, 12);continue;}double x=mpas_f32_to_f64_ieee(t.bv);b+=v==v1?x:-x;}float out=mpas_f64_to_f32_ieee(b);if(!isfinite(out))m4_fail(failure,slot, 3, i, 13);bvort[i]=out;}
 for(int e=first;e<ne;e+=stride){unsigned long long slot=nedge+ncell+nvert+e;double b=mpas_f32_to_f64_ieee(bd4[e]);for(int k=0;k<nlev;++k){M4Term t=m4_term(e,k,rho,div,vort,d4,coe,voe,dc,dv,h4,divf,nc,ne,nv,bt_snapshot[k*ne+e]);if(!t.valid){m4_fail(failure,slot, 4, e, 14);continue;}b+=t.b4_64;}float z=mpas_f64_to_f32_ieee(b);if(!isfinite(z))m4_fail(failure,slot, 4, e, 15);bd4[e]=z;}
 __shared__ double partial_h[1024],partial_f[1024];if(blockIdx.x==0){unsigned long long slot=nedge+ncell+nvert+ne+threadIdx.x;double bh=0,bf=0;for(int i=threadIdx.x;i<nlev*ne;i+=blockDim.x){int e=i%ne,k=i/ne;M4Term t=m4_term(e,k,rho,div,vort,d4,coe,voe,dc,dv,h4,divf,nc,ne,nv,bt_snapshot[i]);if(!t.valid){m4_fail(failure,slot, 9, 0, 16);continue;}bh+=t.bh_64;bf+=mpas_f32_to_f64_ieee(t.bfactor);}partial_h[threadIdx.x]=bh;partial_f[threadIdx.x]=bf;__syncthreads();if(threadIdx.x==0){bh=mpas_f32_to_f64_ieee(*bh4);bf=mpas_f32_to_f64_ieee(*bdivf);for(int j=0;j<blockDim.x;++j){bh+=partial_h[j];bf+=partial_f[j];}float x=mpas_f64_to_f32_ieee(bh),y=mpas_f64_to_f32_ieee(bf);if(!isfinite(x)||!isfinite(y))m4_fail(failure,slot, 9, 0, 17);*bh4=x;*bdivf=y;}}
